import { expect, test, type Page } from "@playwright/test";

// Exercise the real chat UI with deterministic results and no model or database.
async function openAnswer(page: Page, rows: Record<string, unknown>[]) {
  const workspace = { id: "precision", name: "Precision", role: "owner" };
  const run = {
    id: "answer",
    kind: "run",
    name: "Compare totals",
    createdAt: "2026-10-10T10:00:00.000Z",
    updatedAt: "2026-10-10T10:00:01.000Z",
    data: {
      goal: "Compare totals",
      status: "succeeded",
      intent: "answer",
      answer: { title: "Totals", rows, citations: [], assumptions: [] },
    },
  };
  await page.route("**/api/v1/**", async (route) => {
    const path = new URL(route.request().url()).pathname;
    if (path.endsWith("/events")) {
      await route.fulfill({ status: 204 });
      return;
    }
    const responses: Record<string, unknown> = {
      "/api/v1/me": {
        user: { id: "local-user", name: "Local user" },
        workspaces: [workspace],
      },
      "/api/v1/workspaces/precision/onboarding": { complete: true },
      "/api/v1/workspaces/precision/threads": { items: [] },
      "/api/v1/workspaces/precision/threads/answer": {
        id: "answer",
        title: "Compare totals",
        runs: [run],
      },
    };
    await route.fulfill({
      status: Object.hasOwn(responses, path) ? 200 : 404,
      json: responses[path] ?? { error: "Unexpected fixture request" },
    });
  });
  await page.goto("/analyst/answer");
}

test("Analyst sorts large integers exactly and leaves nulls last", async ({
  page,
}) => {
  await openAnswer(page, [
    { category: "Higher", total: "9007199254740993" },
    { category: "Lower", total: "9007199254740992" },
    { category: "Missing", total: null },
    { category: "Negative", total: "-9007199254740993" },
    { category: "Small", total: 10 },
  ]);
  const grid = page.getByRole("grid", { name: "Totals" });
  const values = grid.locator(
    '[role="row"] [role="gridcell"][aria-colindex="2"]',
  );
  const header = grid.getByRole("columnheader", { name: "Total" });
  await expect(values).toHaveText([
    "9,007,199,254,740,993",
    "9,007,199,254,740,992",
    "null",
    "-9,007,199,254,740,993",
    "10",
  ]);
  await header.getByRole("button").click();
  await expect(header).toHaveAttribute("aria-sort", "ascending");
  await expect(values).toHaveText([
    "-9,007,199,254,740,993",
    "10",
    "9,007,199,254,740,992",
    "9,007,199,254,740,993",
    "null",
  ]);
  await header.getByRole("button").focus();
  await page.keyboard.press("Enter");
  await expect(header).toHaveAttribute("aria-sort", "descending");
  await expect(values).toHaveText([
    "9,007,199,254,740,993",
    "9,007,199,254,740,992",
    "10",
    "-9,007,199,254,740,993",
    "null",
  ]);
  // The chart stays; its tooltips show the exact values.
  await expect(page.locator(".an-chart")).toHaveCount(1);
});

test("Analyst shows the same exact total in a single-result answer", async ({
  page,
}) => {
  await openAnswer(page, [{ total: "9223372036854775807" }]);
  await expect(page.locator(".an-stats dd")).toHaveText(
    "9,223,372,036,854,775,807",
  );
  await page.setViewportSize({ width: 390, height: 844 });
  await page.emulateMedia({ reducedMotion: "reduce" });
  await expect(page.locator(".an-stats dd")).toBeVisible();
});

// Dedicated acceptance installation. Never connects to the user's HelixDB or account store.
import { rm, mkdir } from "node:fs/promises";
import { dataDir, ports } from "./ports.js";
process.env.NODE_ENV = "test";
process.env.DATA_DIR = dataDir;
process.env.APP_ORIGIN = `http://localhost:${ports.web}`;
process.env.EXECUTOR_URL = `http://127.0.0.1:${ports.executor}`;
process.env.INTERNAL_KEY = "acceptance-executor-key-not-for-production";
process.env.ENCRYPTION_KEY = "acceptance-encryption-key-not-for-production";
process.env.OLLAMA_URL = `http://127.0.0.1:${ports.api}/fixture`;
// Every spec shares one IP; polling helpers would exhaust the default budget.
process.env.RATE_LIMIT_MAX ||= "100000";
const { createApp } = await import("../../../apps/api/src/app.js");
const { MemoryStore } = await import("../../../apps/api/src/store.js");
const { startWorker } = await import("../../../apps/api/src/jobs.js");
const { referenceReply, orderRows } = await import(
  "../../fixtures-reference.js"
);
await rm(process.env.DATA_DIR, { recursive: true, force: true });
await mkdir(process.env.DATA_DIR, { recursive: true });
const store = new MemoryStore();
const app = await createApp(store);
app.get("/fixture/api/tags", async () => ({
  models: [
    {
      name: "qwen3:4b",
      digest:
        "359d7dd4bcdab3d86b87d73ac27966f4dbb9f5efdfcc75d34a8764a09474fae7",
    },
  ],
}));
app.post("/fixture/api/chat", async (req: any) => {
  const messages = req.body.messages;
  return {
    message: {
      content: JSON.stringify(
        referenceReply(messages[0].content, JSON.parse(messages[1].content)),
      ),
    },
    prompt_eval_count: 10,
    eval_count: 10,
  };
});
app.get("/fixture/orders", async (req: any) => {
  const offset = Number(req.query.offset || 0),
    limit = Number(req.query.limit || 2);
  return orderRows.slice(offset, offset + limit);
});
await app.listen({ port: ports.api, host: "127.0.0.1" });
const stop = startWorker(store);
process.on("SIGTERM", async () => {
  stop();
  await app.close();
  process.exit(0);
});

import { resolve } from "node:path";
// PW_SLOT (0-9) shifts every port and the data directory so concurrent runs
// (one per agent or worktree) do not collide. Slot 0: API 3101, executor 3102,
// web 5174, .data/browser-isolated. Runs in the same slot must be serialized.
const slot = Math.min(
  Math.max(Math.trunc(Number(process.env.PW_SLOT)) || 0, 0),
  9,
);
export const ports = {
  api: 3101 + slot * 10,
  executor: 3102 + slot * 10,
  web: 5174 + slot * 10,
};
export const dataDir = resolve(
  ".data/browser-isolated" + (slot ? "-" + slot : ""),
);
// Screenshots and saved browser state from specs.
export const artifact = (name: string) => `${dataDir}/${name}`;

// Shared browser-test setup: open the isolated app and build a finished
// workspace from the sample data (demo -> ontology -> confirm -> published).
import { expect, type Page } from "@playwright/test";

// No sign-in: the first request sets up this computer's person and a workspace.
// Specs run in any order, so this works whether or not that already happened.
export async function openApp(page: Page) {
  const me = page.waitForResponse(
    (r) =>
      new URL(r.url()).pathname === "/api/v1/me" &&
      r.request().method() === "GET",
  );
  await page.goto("/");
  expect((await me).status()).toBe(200);
  // The app then remembers a workspace. Wait for that write so a test's own
  // choice of workspace is not overwritten by it.
  await page.waitForFunction(() => !!localStorage.getItem("foundry.workspace"));
}

export async function api(page: Page, path: string, data?: unknown) {
  const response =
    data === undefined
      ? await page.request.get("/api/v1" + path)
      : await page.request.post("/api/v1" + path, { data });
  expect(response.ok(), await response.text()).toBeTruthy();
  return response.json();
}

// A published workspace built from the sample data; selected in the browser.
export async function sampleWorkspace(page: Page, name: string) {
  const workspace = await api(page, "/workspaces", { name });
  const base = `/workspaces/${workspace.id}`;
  await api(page, base + "/onboarding/provider", {
    provider: "local",
    model: "qwen3:4b",
  });
  await api(page, base + "/demo", { advance: true });
  await expect
    .poll(
      async () => {
        const s = await api(page, base + "/onboarding");
        return s.providerReady && !s.sampleProgress;
      },
      { timeout: 60000, intervals: [1000] },
    )
    .toBe(true);
  const state = await api(page, base + "/onboarding/ontology", {});
  await api(page, base + "/onboarding/ontology/confirm", {
    hash: state.ontology.hash,
    excluded: [],
    names: {},
  });
  await expect
    .poll(async () => (await api(page, base + "/onboarding")).complete, {
      timeout: 90000,
      intervals: [1000],
    })
    .toBe(true);
  await page.evaluate(
    (id) => localStorage.setItem("foundry.workspace", id),
    workspace.id,
  );
  return { id: workspace.id as string, name, base };
}

{
  "name": "@helix-foundry/sdk",
  "version": "0.1.0",
  "description": "TypeScript client for self-hosted Helix Foundry workspaces",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@helix-foundry/shared": "workspace:*"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "scripts": {
    "build": "tsc -p tsconfig.build.json"
  },
  "license": "Apache-2.0"
}

import { z } from "zod";
import type { Resource } from "../../../packages/shared/src/index.js";
import { resource, transaction, type Store, type Tx } from "./store.js";
import { assert, digest } from "./security.js";
export const ObjectActionSchema = z.discriminatedUnion("operation", [
  z.object({
    operation: z.literal("create"),
    objectType: z.string(),
    values: z.record(z.string(), z.unknown()),
  }),
  z.object({
    operation: z.enum(["link", "unlink"]),
    name: z.string().min(1).max(120),
    from: z.string(),
    to: z.string(),
  }),
]);
export type ObjectAction = z.infer<typeof ObjectActionSchema>;
async function resolveAction(
  store: Pick<Store, "get" | "list" | "getMany" | "relationsBetween">,
  scope: string,
  action: ObjectAction,
) {
  const ws = await store.get(scope, "workspace");
  assert(ws?.data.activeGeneration, "Publish an ontology first");
  const generation = ws.data.activeGeneration;
  if (action.operation === "create") {
    const type = (await store.list(scope, "objectType")).find(
      (t) => t.data.generation === generation && t.name === action.objectType,
    );
    assert(type, "Object type unavailable");
    assert(
      Object.keys(action.values).every((k) => type.data.properties.includes(k)),
      "Unknown object property",
    );
    const key = action.values[type.data.primaryKey];
    assert(
      key !== null && key !== undefined && String(key).length > 0,
      "A primary key is required",
    );
    const logicalId = digest(type.data.typeId + ":" + String(key)).slice(0, 32);
    assert(
      !(await store.get(scope, generation + "_" + logicalId)),
      "An object with this key already exists",
      409,
    );
    return {
      generation,
      logicalId,
      typeId: type.data.typeId,
      key: String(key),
      before: null,
      after: action.values,
    };
  }
  const from = await store.get(scope, action.from),
    to = await store.get(scope, action.to);
  assert(
    from?.kind === "object" &&
      to?.kind === "object" &&
      from.data.generation === generation &&
      to.data.generation === generation,
    "Objects unavailable",
    404,
  );
  // Read from the record's own links, not every relation in the workspace.
  const relations = (
    await store.getMany(
      scope,
      await store.relationsBetween(scope, from.id, to.id, action.name),
    )
  ).filter(
    (r): r is Resource =>
      !!r &&
      r.data.generation === generation &&
      r.data.from === from.id &&
      r.data.to === to.id,
  );
  const editId =
    "relationEdit_" +
    digest([from.data.logicalId, to.data.logicalId, action.name].join(":"));
  const prior = await store.get(scope, editId);
  return {
    generation,
    fromName: from.name,
    toName: to.name,
    fromLogicalId: from.data.logicalId,
    toLogicalId: to.data.logicalId,
    editId,
    revision: prior?.revision || 0,
    relations: relations.map((r) => r.id),
    before: relations.length > 0,
    after: action.operation === "link",
  };
}
export async function previewObjectAction(
  store: Store,
  scope: string,
  action: ObjectAction,
) {
  const evidence = await resolveAction(store, scope, action);
  return {
    action,
    evidence,
    hash: digest(JSON.stringify({ action, evidence })),
  };
}
export async function executeObjectAction(
  store: Store,
  scope: string,
  action: ObjectAction,
  hash: string,
  idempotencyKey: string,
  actor: string,
) {
  return transaction(store, scope, async (tx) => {
    const auditId = "action_" + digest(idempotencyKey),
      requestHash = digest(JSON.stringify({ action, hash })),
      prior = await tx.get(auditId);
    if (prior) {
      assert(
        prior.data.requestHash === requestHash,
        "Idempotency key reused",
        409,
      );
      return prior;
    }
    const scoped = {
      get: (_s: string, id: string) => tx.get(id),
      list: (_s: string, kind: string) => tx.list(kind),
      getMany: (_s: string, ids: string[]) =>
        Promise.all(ids.map((id) => tx.get(id))),
      relationsBetween: store.relationsBetween.bind(store),
    };
    const evidence: any = await resolveAction(scoped, scope, action);
    assert(
      hash === digest(JSON.stringify({ action, evidence })),
      "Action preview is stale",
      409,
    );
    if (action.operation === "create") {
      const base = {
        type: action.objectType,
        typeId: evidence.typeId,
        key: evidence.key,
        logicalId: evidence.logicalId,
        base: action.values,
        manual: true,
      };
      const type = (await tx.list("objectType")).find(
        (t) =>
          t.data.generation === evidence.generation &&
          t.name === action.objectType,
      );
      if (type)
        tx.update(type, {
          ...type.data,
          objectCount: (type.data.objectCount || 0) + 1,
        });
      tx.put(
        resource(
          scope,
          "manualObject",
          `${action.objectType} ${evidence.key}`,
          base,
          "manual_" + evidence.logicalId,
        ),
      );
      tx.put(
        resource(
          scope,
          "object",
          `${action.objectType} ${evidence.key}`,
          { ...base, generation: evidence.generation },
          evidence.generation + "_" + evidence.logicalId,
        ),
      );
    } else {
      const old = await tx.get(evidence.editId);
      tx.put({
        ...resource(
          scope,
          "relationEdit",
          action.name,
          {
            fromLogicalId: evidence.fromLogicalId,
            toLogicalId: evidence.toLogicalId,
            enabled: action.operation === "link",
          },
          evidence.editId,
        ),
        revision: (old?.revision || 0) + 1,
      });
      for (const id of evidence.relations) tx.delete(id);
      if (action.operation === "link")
        tx.put(
          resource(
            scope,
            "relation",
            action.name,
            {
              from: action.from,
              to: action.to,
              generation: evidence.generation,
            },
            // As publication names it, so the generation's id prefix finds it.
            `${evidence.generation}_r${digest(
              [action.name, evidence.fromLogicalId, evidence.toLogicalId].join(
                ":",
              ),
            ).slice(0, 32)}`,
          ),
        );
    }
    return tx.put(
      resource(
        scope,
        "audit",
        action.operation === "create"
          ? "Created " + action.objectType
          : "Relationship " + action.operation,
        { actor, action, evidence, requestHash },
        auditId,
      ),
    );
  });
}

import {
  ProviderSchema,
  type Resource,
} from "../../../packages/shared/src/index.js";
import { config } from "./config.js";
import { AppError, assert, seal, unseal } from "./security.js";
import { transaction, resource, now, type Store } from "./store.js";
import { testProvider, verifyPinnedModel } from "./providers.js";

export async function jobProgress(
  store: Store,
  scope: string,
  id: string,
  progress: Record<string, unknown>,
) {
  return transaction(store, scope, async (tx) => {
    const job = await tx.get(id);
    assert(job && job.data.status !== "canceled", "Operation canceled", 409);
    tx.update(job, { ...job.data, progress });
  });
}
export async function prepareProvider(
  store: Store,
  scope: string,
  job: Resource,
) {
  const settings = ProviderSchema.parse(unseal(job.data.secret));
  const controller = new AbortController();
  const cancellation = setInterval(
    () =>
      void store.get(scope, job.id).then((j) => {
        if (j?.data.status === "canceled") controller.abort();
      }),
    1000,
  );
  try {
    if (settings.provider === "local") {
      let installed = false;
      if (settings.model === "qwen3:4b") {
        try {
          await verifyPinnedModel(settings);
          installed = true;
        } catch {
          /* Pull missing/pin-mismatched models, then verify again. */
        }
      } else {
        const tags = (await fetch(
          (settings.baseUrl || config.ollama) + "/api/tags",
          { signal: AbortSignal.timeout(5000) },
        ).then((r) => r.json())) as any;
        installed = tags.models?.some((m: any) => m.name === settings.model);
      }
      if (!installed) {
        await jobProgress(store, scope, job.id, {
          message: "Downloading local model",
        });
        const response = await fetch(
          (settings.baseUrl || config.ollama) + "/api/pull",
          {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ model: settings.model, stream: true }),
            signal: AbortSignal.any([
              controller.signal,
              AbortSignal.timeout(1800000),
            ]),
          },
        );
        assert(
          response.ok && response.body,
          "Local AI is unavailable. Start Ollama and retry.",
          502,
        );
        const reader = response.body
          .pipeThrough(new TextDecoderStream())
          .getReader();
        let pending = "",
          last = 0;
        const report = async (line: string) => {
          const p = JSON.parse(line);
          assert(
            !p.error,
            "Model download failed. Check model availability and retry.",
            502,
          );
          if (Date.now() - last > 500 || p.status === "success") {
            last = Date.now();
            await jobProgress(store, scope, job.id, {
              message: p.status,
              completed: p.completed,
              total: p.total,
            });
          }
        };
        try {
          while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            pending += value;
            let i;
            while ((i = pending.indexOf("\n")) >= 0) {
              const line = pending.slice(0, i);
              pending = pending.slice(i + 1);
              if (line.trim()) await report(line);
            }
          }
          if (pending.trim()) await report(pending);
        } finally {
          await reader.cancel();
        }
      }
    }
    await jobProgress(store, scope, job.id, {
      message: "Testing connection and structured output",
    });
    const tested = await testProvider(
      settings,
      AbortSignal.any([
        controller.signal,
        AbortSignal.timeout(settings.timeoutSeconds * 1000),
      ]),
    );
    await transaction(store, scope, async (tx) => {
      const current = await tx.get(job.id),
        workspace = await tx.get("workspace");
      assert(
        current?.data.status !== "canceled" &&
          workspace?.data.onboarding?.providerJobId === job.id,
        "Provider preparation was replaced",
        409,
      );
      const member = await store.get("global", `${job.data.actor}:${scope}`);
      assert(
        member?.data.role === "owner",
        "Owner permission is no longer available",
        403,
      );
      const previous = await tx.get("provider");
      const data = {
        settings: { ...settings, apiKey: undefined },
        secret: settings.apiKey ? seal(settings.apiKey) : null,
        testedAt: now(),
      };
      if (previous) tx.update(previous, data);
      else tx.put(resource(scope, "provider", "AI provider", data, "provider"));
      tx.update(current!, {
        ...current!.data,
        status: "succeeded",
        tokens: tested.tokens,
        progress: { message: "AI is ready" },
      });
    });
  } catch (e) {
    // Ollama not running shows up as a bare network error.
    if (
      settings.provider === "local" &&
      e instanceof TypeError &&
      e.message === "fetch failed"
    )
      throw new AppError(
        502,
        "Local AI is unavailable. Start Ollama and retry.",
      );
    throw e;
  } finally {
    clearInterval(cancellation);
  }
}

import {
  createHash,
  randomBytes,
  createCipheriv,
  createDecipheriv,
} from "node:crypto";
import { config } from "./config.js";
export const digest = (v: string) =>
  createHash("sha256").update(v).digest("hex");
export const token = () => randomBytes(32).toString("base64url");
export function seal(data: unknown) {
  const iv = randomBytes(12),
    cipher = createCipheriv(
      "aes-256-gcm",
      createHash("sha256").update(config.encryptionKey).digest(),
      iv,
    );
  const encrypted = Buffer.concat([
    cipher.update(JSON.stringify(data), "utf8"),
    cipher.final(),
  ]);
  return [
    iv.toString("base64"),
    cipher.getAuthTag().toString("base64"),
    encrypted.toString("base64"),
  ].join(".");
}
export function unseal<T = Record<string, any>>(value: string): T {
  const [iv, tag, body] = value.split(".").map((x) => Buffer.from(x, "base64"));
  const cipher = createDecipheriv(
    "aes-256-gcm",
    createHash("sha256").update(config.encryptionKey).digest(),
    iv,
  );
  cipher.setAuthTag(tag);
  return JSON.parse(
    Buffer.concat([cipher.update(body), cipher.final()]).toString(),
  );
}
export class AppError extends Error {
  constructor(
    public statusCode: number,
    message: string,
  ) {
    super(message);
  }
}
export function assert(
  condition: unknown,
  message: string,
  status = 400,
): asserts condition {
  if (!condition) throw new AppError(status, message);
}
// Error text can reach the AI provider, so credentials in it are replaced.
// A database URL goes whole; any other URL keeps its host but not its user
// and password. An Authorization value goes up to the end of the line or a
// comma, semicolon or brace, since Basic and PlanetScale's ID:TOKEN have no
// fixed shape, and so does the word after any Bearer. A named secret's value
// goes, quoted or not, also under a JSON key; a :: cast is not a separator.
// The keys of the services Foundry connects to go by their prefix only when
// a long token follows, so DuckDB names such as sk_customer_key or sbp_mmhg
// stay and a failed query can still be repaired. Callers cut the result to
// length afterwards, so a match is never split.
export function redact(message: string) {
  return message
    .replace(
      /\b(postgres(?:ql)?|mysql|neo4j(?:\+s)?|bolt(?:\+s)?):\/\/[^\s]+/gi,
      "$1://[redacted]",
    )
    .replace(
      /(?<![a-z0-9+.-])([a-z][a-z0-9+.-]*:\/\/)[^\s/?#]*@/gi,
      "$1[redacted]@",
    )
    .replace(
      /(authorization\\?["']?\s*(?:=|:(?!:))\s*)(?:"(?:[^"\\]|\\.)*"|\\"[^"]*"|'[^']*'|[^\r\n,;}]+)/gi,
      "$1[redacted]",
    )
    .replace(
      /((?:password|passwd|secret|token|(?:api|access|secret|private|internal|encryption)[_-]?key)\\?["']?\s*(?:=|:(?!:))\s*)(?:"(?:[^"\\]|\\.)*"|\\"[^"]*"|'[^']*'|[^\s,;]+)/gi,
      "$1[redacted]",
    )
    .replace(/\b(bearer)\s+[^\s,;"']+/gi, "$1 [redacted]")
    .replace(
      /\b(?:[sr]k_(?:live|test)|phx|napi|sbp|pscale_(?:tkn|pw|oauth))_[a-zA-Z0-9]{20}[\w-]*|\bsk-[\w-]{20,}/g,
      "[redacted]",
    );
}

