// A separate installation whose store can be seeded before its first request.
async function freshApp(seed?: (s: MemoryStore) => Promise<void>) {
  const s = new MemoryStore();
  await seed?.(s);
  const a = await createApp(s);
  await a.ready();
  return { store: s, app: a };
}
