test("native Analyst profit answers show signed bars around zero on desktop and mobile", async ({
  page,
}, testInfo) => {
  await openApp(page);
  const ws = await api(page, "/workspaces", {
    name: "Signed charts " + Date.now(),
  });
  const base = `/workspaces/${ws.id}`;
  await page.evaluate(
    (id) => localStorage.setItem("foundry.workspace", id),
    ws.id,
  );
  await api(page, base + "/onboarding/provider", {
    provider: "local",
    model: "qwen3:4b",
  });
  const cases: [string, number[]][] = [
    ["mixed", [-50, 100, 0]],
    ["negative", [-80, -20]],
    ["positive", [100, 25]],
    ["zero", [0, 0]],
  ];
  let published = false;
  for (const [name, values] of cases) {
    const goal = "Signed breakdown " + name;
    const ds = await api(page, base + "/ingest", {
      name: goal,
      rows: values.map((profit, i) => ({ category: `Category ${i}`, profit })),
    });
    if (!published) {
      const proposal = (
        await api(page, base + "/definitions/import", {
          version: 1,
          proposals: [
            {
              summary: "Profit analysis",
              assumptions: [],
              catalog: [],
              pipelines: [],
              ontology: [],
              relationships: [],
              dashboards: [
                {
                  name: "Profit",
                  widgets: [
                    {
                      title: "Profit",
                      type: "metric",
                      inputs: [ds.id],
                      sql: `SELECT sum(profit) profit FROM ${datasetTable(ds.id)}`,
                    },
                  ],
                },
              ],
              actions: [],
            },
          ],
        })
      ).items[0];
      expect(proposal.data.validation.valid).toBe(true);
      await api(page, base + `/proposals/${proposal.id}/publish`, {
        hash: proposal.data.hash,
      });
      published = true;
    }
    const run = await api(page, base + "/assistant/runs", {
      goal,
      intent: "answer",
    });
    let done: any;
    await expect
      .poll(
        async () => {
          done = await api(page, base + `/resources/run/${run.id}`);
          return done.data.status;
        },
        { timeout: 30000 },
      )
      .toBe("succeeded");
    expect(done.data.answer.rows.map((r: any) => Number(r.profit))).toEqual(
      values,
    );
    expect(done.data.answer.citations).toContainEqual(
      expect.objectContaining({
        datasetId: ds.id,
        version: ds.data.activeVersion,
      }),
    );
    await page.goto("/analyst/" + run.id);
    const chart = page.locator(".an-chart");
    await expect(chart).toBeVisible();
    for (const width of [1440, 390]) {
      await page.setViewportSize({ width, height: 844 });
      await page.emulateMedia({ reducedMotion: "reduce" });
      const bars = chart.locator(".wk-bar");
      await expect(bars).toHaveCount(values.length);
      const geometry = await bars.evaluateAll((els) =>
        els.map((el) => {
          const bar = el.getBoundingClientRect(),
            track = el.parentElement!.getBoundingClientRect();
          return {
            width: bar.width / track.width,
            left: (bar.left - track.left) / track.width,
          };
        }),
      );
      const lower = Math.min(0, ...values),
        upper = Math.max(0, ...values),
        range = upper - lower || 1;
      for (let i = 0; i < values.length; i++) {
        expect(geometry[i].width).toBeCloseTo(Math.abs(values[i]) / range, 2);
        expect(geometry[i].left).toBeCloseTo(
          (Math.min(0, values[i]) - lower) / range,
          2,
        );
      }
      if (values.some((v) => v < 0)) {
        const zeroLines = chart.locator(".wk-bar-zero");
        await expect(zeroLines).toHaveCount(values.length);
        const visible = await zeroLines.evaluateAll((els) =>
          els.map((el) => {
            const style = getComputedStyle(el);
            return {
              width: style.borderLeftWidth,
              style: style.borderLeftStyle,
              color: style.borderLeftColor,
            };
          }),
        );
        for (const line of visible) {
          expect(line.width).toBe("1px");
          expect(line.style).toBe("solid");
          expect(line.color).not.toBe("rgba(0, 0, 0, 0)");
        }
      }
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
    }
    await page.screenshot({
      path: testInfo.outputPath(name + "-mobile.png"),
      fullPage: true,
    });
    const image = chart.getByRole("img");
    await image.focus();
    await expect(chart.locator('[aria-live="polite"]')).toHaveText(
      `Category 0: ${values[0]}`,
    );
    await page.keyboard.press("ArrowDown");
    await expect(chart.locator('[aria-live="polite"]')).toHaveText(
      `Category 1: ${values[1]}`,
    );
  }
});

import { test, expect } from "@playwright/test";
import { readFile } from "node:fs/promises";
import { parse } from "csv-parse/sync";
import { api, openApp } from "./support/workspace";
test("dataset details download every row as CSV through the real executor", async ({
  page,
}) => {
  await openApp(page);
  const workspace = await api(page, "/workspaces", {
    name: "CSV download " + Date.now(),
  });
  await page.evaluate(
    (id) => localStorage.setItem("foundry.workspace", id),
    workspace.id,
  );
  const dataset = await api(page, `/workspaces/${workspace.id}/ingest`, {
    name: "CSV acceptance",
    rows: Array.from({ length: 75 }, (_, i) => ({
      id: i,
      note: i === 74 ? 'last, "quoted"\nrow' : "row " + i,
    })),
  });
  await page.goto(`/data/datasets/${dataset.id}`);
  await page.getByText("Details", { exact: true }).click();
  const exported = page.waitForEvent("download");
  await page.getByRole("link", { name: "Export CSV", exact: true }).click();
  const download = await exported;
  expect(download.suggestedFilename()).toBe("dataset.csv");
  const path = await download.path();
  expect(path).toBeTruthy();
  const rows = parse(await readFile(path!, "utf8"), { columns: true });
  expect(rows).toHaveLength(75);
  expect(rows.at(-1)).toEqual({ id: "74", note: 'last, "quoted"\nrow' });
  await expect(
    page.getByRole("link", { name: "Export Parquet", exact: true }),
  ).toBeVisible();
});

import { test, expect } from "@playwright/test";
import { api, openApp } from "./support/workspace";

test("Developer tools show saved token metadata and revoke only the selected integration", async ({
  page,
}) => {
  await openApp(page);
  const workspace = await api(page, "/workspaces", {
    name: "Token lifecycle " + Date.now(),
  });
  await page.evaluate(
    (id) => localStorage.setItem("foundry.workspace", id),
    workspace.id,
  );
  const keep = await api(page, `/workspaces/${workspace.id}/tokens`, {
    name: "Existing notebook",
    readOnly: true,
  });
  await page.goto("/settings?tab=developer");
  const inventory = page.getByRole("region", { name: "Active API tokens" });
  await expect(inventory).toContainText("Existing notebook");
  await expect(inventory).toContainText("Read-only");
  const created = page.waitForResponse(
    (r) =>
      r.request().method() === "POST" &&
      new URL(r.url()).pathname === `/api/v1/workspaces/${workspace.id}/tokens`,
  );
  await page.getByLabel("Token name").fill("New automation");
  await page.getByLabel("Read-only access").uncheck();
  await page.getByRole("button", { name: "Create API token" }).click();
  const issued = await (await created).json();
  await expect(inventory).toContainText("New automation");
  await expect(inventory).toContainText("Read and write");
  await expect(page.locator(".copy-box code")).toHaveText(issued.token);
  await page.reload();
  await expect(inventory).toContainText("New automation");
  await expect(page.locator(".copy-box")).toHaveCount(0);
  await page.getByRole("button", { name: "Revoke New automation" }).click();
  const confirm = page.getByRole("dialog", {
    name: "Revoke “New automation”?",
  });
  await expect(confirm).toContainText(
    "Integrations that use this token will stop working.",
  );
  await confirm.getByRole("button", { name: "Revoke token" }).click();
  await expect(confirm).toHaveCount(0);
  await expect(inventory).not.toContainText("New automation");
  await expect(inventory).toContainText("Existing notebook");
  const revoked = await page.request.get(
    `/api/v1/workspaces/${workspace.id}/overview`,
    { headers: { authorization: "Bearer " + issued.token } },
  );
  expect(revoked.status()).toBe(401);
  const retained = await page.request.get(
    `/api/v1/workspaces/${workspace.id}/overview`,
    { headers: { authorization: "Bearer " + keep.token } },
  );
  expect(retained.status()).toBe(200);
});

import { test, expect, type Page } from "@playwright/test";
import { api, openApp, sampleWorkspace } from "./support/workspace";
import { artifact } from "./support/ports";

// The voice interface around a GPT-Live session: the orb, the transcript in
// the composer, Home -> chat continuity and cleanup. GPT-Live itself can't run
// here, so the WebRTC peer and the session endpoints are stand-ins; the chat,
// its runs and the Analyst are real. tests/live.test.ts covers the server.

// A fake peer connection whose event channel the test drives, and a silent
// microphone made from an audio graph so its tracks are real.
async function fakeVoice(page: Page) {
  await page.addInitScript(() => {
    const w = window as any;
    w.__voice = {
      sent: [] as any[],
      channel: null as any,
      tracks: [] as any[],
    };
    class Channel extends EventTarget {
      readyState = "connecting";
      label: string;
      constructor(label: string) {
        super();
        this.label = label;
      }
      send(data: string) {
        w.__voice.sent.push(JSON.parse(data));
      }
      close() {
        this.readyState = "closed";
      }
    }
    class Peer extends EventTarget {
      connectionState = "new";
      iceGatheringState = "complete";
      localDescription: any = null;
      createDataChannel(label: string) {
        const c = new Channel(label);
        w.__voice.channel = c;
        return c;
      }
      addTrack() {}
      async createOffer() {
        return { type: "offer", sdp: "v=0 fake-offer" };
      }
      async setLocalDescription(d: any) {
        this.localDescription = d;
      }
      async setRemoteDescription() {
        setTimeout(() => {
          this.connectionState = "connected";
          w.__voice.channel.readyState = "open";
          w.__voice.emit({
            type: "session.started",
            session: { id: "live_test" },
          });
        }, 50);
      }
      close() {
        this.connectionState = "closed";
      }
    }
    w.RTCPeerConnection = Peer;
    w.__voice.emit = (event: unknown) =>
      w.__voice.channel.dispatchEvent(
        new MessageEvent("message", { data: JSON.stringify(event) }),
      );
    navigator.mediaDevices.getUserMedia = async () => {
      if (w.__denyMic)
        throw new DOMException("Permission denied", "NotAllowedError");
      const stream = new AudioContext().createMediaStreamDestination().stream;
      w.__voice.tracks.push(...stream.getTracks());
      return stream;
    };
  });
}
const emit = (page: Page, event: unknown) =>
  page.evaluate((e) => (window as any).__voice.emit(e), event);
const micState = (page: Page) =>
  page.evaluate(() =>
    (window as any).__voice.tracks.map((t: MediaStreamTrack) =>
      t.readyState === "ended" ? "ended" : t.enabled ? "on" : "paused",
    ),
  );

test("hands-free voice continues from Home into the chat", async ({ page }) => {
  await fakeVoice(page);
  await openApp(page);
  const ws = await sampleWorkspace(page, "Voice " + Date.now());
  // The sample workspace uses the local model: no voice.
  await page.goto("/");
  await expect(
    page.getByRole("textbox", { name: "Ask anything about your data" }),
  ).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Start voice conversation" }),
  ).toHaveCount(0);

  // With OpenAI and GPT-Live access, the session endpoints answer.
  const claims: { runId: string; chatId: string; question: string }[] = [];
  await page.route("**/api/v1/workspaces/*/live", (r) =>
    r.fulfill({ json: { available: true } }),
  );
  let sessionRequest: any;
  await page.route("**/api/v1/workspaces/*/live/sessions", (r) => {
    sessionRequest = r.request().postDataJSON();
    return r.fulfill({
      json: {
        sessionId: "live_test",
        sdp: "v=0 fake-answer",
        chatId: sessionRequest.chatId ?? null,
      },
    });
  });
  await page.route("**/live/sessions/live_test/**", (r) => {
    const url = r.request().url();
    if (url.includes("/delegations/")) {
      const c = claims.shift()!;
      return r.fulfill({
        json: { status: "running", action: "ask", error: null, ...c },
      });
    }
    return r.fulfill({ json: { ok: true } });
  });
  await page.route("**/live/sessions/live_test", (r) =>
    r.fulfill({ json: { ok: true } }),
  );
  await page.reload();
  const orb = page.getByRole("button", { name: "Start voice conversation" });
  await expect(orb).toBeVisible();
  // Nothing is captured until the orb is pressed.
  expect(await micState(page)).toEqual([]);

  await orb.click();
  const stop = page.getByRole("button", { name: "Stop voice conversation" });
  await expect(stop).toHaveAttribute("aria-pressed", "true");
  await expect(stop).toHaveClass(/is-live/);
  expect(sessionRequest).toMatchObject({ sdp: "v=0 fake-offer", chatId: null });
  await expect(page.getByText("Listening · speak naturally")).toBeVisible();

  // The user's words appear in the Ask box as they speak.
  const home = page.getByRole("textbox", {
    name: "Ask anything about your data",
  });
  await emit(page, {
    type: "session.input_transcript.delta",
    delta: "How many orders",
    start_ms: 1000,
    end_ms: 1400,
  });
  await emit(page, {
    type: "session.input_transcript.delta",
    delta: " do we have?",
    start_ms: 1400,
    end_ms: 1800,
  });
  await expect(home).toHaveValue("How many orders do we have?");
  await page.screenshot({ path: artifact("voice-home.png") });

  // GPT-Live delegates; the server answers with an ordinary Analyst run,
  // which opens its chat. Voice stays on.
  const first = await api(page, `${ws.base}/assistant/runs`, {
    goal: "How many orders do we have?",
    intent: "answer",
  });
  claims.push({
    runId: first.id,
    chatId: first.id,
    question: "How many orders do we have?",
  });
  await emit(page, {
    type: "session.delegation.created",
    offset_ms: 1900,
    delegation: { id: "item_1", type: "delegation", target: "client" },
  });
  await expect(page).toHaveURL(new RegExp(`/analyst/${first.id}$`));
  const chatStop = page.getByRole("button", {
    name: "Stop voice conversation",
  });
  await expect(chatStop).toHaveClass(/is-live/);
  await expect(page.locator(".an-question").first()).toContainText(
    "How many orders do we have?",
  );
  const composer = page.getByRole("textbox", { name: "Ask a follow-up" });
  await expect(composer).toHaveValue("");

  // The assistant's words show under the composer while it speaks.
  await emit(page, {
    type: "session.output_transcript.delta",
    delta: "Checking that now.",
    start_ms: 2000,
    end_ms: 2600,
  });
  await expect(page.locator(".an-hint")).toHaveText("Checking that now.");

  // A follow-up, hands-free: the words show in the chat composer.
  await emit(page, {
    type: "session.input_transcript.delta",
    delta: "Which customers ordered most?",
    start_ms: 5000,
    end_ms: 6200,
  });
  await expect(composer).toHaveValue("Which customers ordered most?");
  await page.screenshot({ path: artifact("voice-chat-desktop.png") });

  // Typing takes the composer back and pauses the microphone; clearing the
  // text resumes listening. A typed draft is never sent by voice.
  await composer.press("End");
  await composer.pressSequentially(" by revenue");
  await expect(composer).toHaveValue(
    "Which customers ordered most? by revenue",
  );
  await expect(page.locator(".an-hint")).toContainText("Voice paused");
  expect(await micState(page)).toEqual(["paused"]);
  await composer.fill("");
  await expect(page.locator(".an-hint")).not.toContainText("Voice paused");
  expect(await micState(page)).toEqual(["on"]);

  // Phone width: the same chat, orb centred above the composer.
  await page.setViewportSize({ width: 390, height: 844 });
  const box = (await chatStop.boundingBox())!,
    form = (await page.locator(".an-composer").boundingBox())!;
  expect(box.y + box.height).toBeLessThanOrEqual(form.y + 1);
  expect(
    Math.abs(box.x + box.width / 2 - (form.x + form.width / 2)),
  ).toBeLessThan(4);
  expect(box.width).toBeGreaterThanOrEqual(44);
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= window.innerWidth,
    ),
  ).toBe(true);
  await expect(page.locator(".an-hint")).toHaveText(
    "Listening · speak naturally · Esc to stop",
  );
  await page.screenshot({ path: artifact("voice-chat-mobile.png") });
  // Reduced motion keeps the glow but stops its pulse.
  await page.emulateMedia({ reducedMotion: "reduce" });
  expect(
    await page
      .locator(".hf-voice-orb-mark")
      .evaluate((el) => getComputedStyle(el).animationName),
  ).toBe("none");
  await page.setViewportSize({ width: 1440, height: 1040 });

  // Escape ends voice: the session is closed and the microphone released.
  await page.keyboard.press("Escape");
  await expect(
    page.getByRole("button", { name: "Start voice conversation" }),
  ).toHaveAttribute("aria-pressed", "false");
  await expect.poll(() => micState(page)).toEqual(["ended"]);
  expect(
    await page.evaluate(() =>
      (window as any).__voice.sent.map((c: any) => c.type),
    ),
  ).toContain("session.close");
  await expect(composer).toBeEditable();

  // Starting in an existing chat continues that chat; leaving it ends voice.
  await page.getByRole("button", { name: "Start voice conversation" }).click();
  await expect(chatStop).toHaveClass(/is-live/);
  expect(sessionRequest.chatId).toBe(first.id);
  await page
    .getByRole("navigation", { name: "Main navigation" })
    .getByRole("link", { name: "Data", exact: true })
    .click();
  await expect(page).toHaveURL(/\/data$/);
  await expect.poll(async () => (await micState(page)).at(-1)).toBe("ended");
  await page.goBack();
  await expect(page).toHaveURL(new RegExp(`/analyst/${first.id}$`));
  await expect(
    page.getByRole("button", { name: "Start voice conversation" }),
  ).toHaveAttribute("aria-pressed", "false");

  // A blocked microphone says so, and typing still works.
  await page.evaluate(() => ((window as any).__denyMic = true));
  await page.getByRole("button", { name: "Start voice conversation" }).click();
  await expect(page.getByRole("alert")).toContainText(
    "Microphone access was blocked",
  );
  await expect(
    page.getByRole("button", { name: "Start voice conversation" }),
  ).not.toHaveClass(/is-live/);
  await expect(composer).toBeEditable();
});

import { test, expect } from "@playwright/test";
import { api, openApp, sampleWorkspace } from "./support/workspace";

test("workspace shell: navigation, search, setup gate and errors", async ({
  page,
}) => {
  await openApp(page);
  // An unfinished workspace sends every workspace route to setup.
  const fresh = await api(page, "/workspaces", {
    name: "Shell setup " + Date.now(),
  });
  await page.evaluate(
    (id) => localStorage.setItem("foundry.workspace", id),
    fresh.id,
  );
  for (const path of ["/ontology", "/analyst", "/"]) {
    await page.goto(path);
    await expect(page).toHaveURL(/\/onboarding$/);
  }
  // Data stays open: setup sends people to a dataset to accept a schema change.
  const dataset = await api(page, `/workspaces/${fresh.id}/ingest`, {
    name: "Gate check",
    rows: [{ id: 1, name: "A" }],
  });
  await page.goto(`/data/datasets/${dataset.id}`);
  await expect(
    page.getByRole("heading", { name: "Gate check", exact: true }),
  ).toBeVisible();
  await expect(page).toHaveURL(new RegExp(`/data/datasets/${dataset.id}$`));
  await page.goto("/data");
  await expect(page).toHaveURL(/\/data$/);
  const ws = await sampleWorkspace(page, "Shell " + Date.now());
  await page.goto("/");
  const nav = page.getByRole("navigation", { name: "Main navigation" });
  // Ontology second, then Data and Analyst.
  const sections = ["Home", "Ontology", "Data", "Analyst"];
  for (const label of sections)
    await expect(
      nav.getByRole("link", { name: label, exact: true }),
    ).toBeVisible();
  expect(
    (await nav.locator(".hf-nav-link").allInnerTexts()).map((t) => t.trim()),
  ).toEqual(sections);
  // Settings sits in the sidebar footer beside the Preferences menu, which
  // names this computer rather than a signed-in person.
  const footer = page.locator(".hf-sidebar-foot");
  await expect(footer.getByRole("link", { name: "Settings" })).toBeVisible();
  const preferences = footer.getByRole("button", {
    name: "Preferences",
    exact: true,
  });
  await expect(preferences).toContainText("This computer");
  await preferences.click();
  const preferencesMenu = page.getByRole("menu", { name: "Preferences" });
  await expect(
    preferencesMenu.getByRole("menuitem", { name: "Settings" }),
  ).toBeVisible();
  await expect(
    preferencesMenu.getByRole("menuitem", { name: "Sign out" }),
  ).toHaveCount(0);
  await page.keyboard.press("Escape");
  await expect(preferencesMenu).toHaveCount(0);
  // SQL, Pipelines, Activity and Dashboards were removed, along with the live
  // activity tray; Home's key metrics replace dashboards.
  for (const label of ["Pipelines", "Activity", "SQL", "Dashboards"])
    await expect(
      nav.getByRole("link", { name: label, exact: true }),
    ).toHaveCount(0);
  await expect(
    page.getByRole("button", { name: /^Live activity/ }),
  ).toHaveCount(0);
  await expect(
    nav.getByRole("link", { name: "Home", exact: true }),
  ).toHaveAttribute("aria-current", "page");
  // The greeting names no one: there are no accounts.
  await expect(page.getByRole("heading", { level: 1 })).toHaveText(
    /^Good (morning|afternoon|evening)$/,
  );
  await expect(
    page.getByRole("region", { name: "Workspace health" }),
  ).toContainText("Connections");
  await expect(
    page.locator(".wk-types").getByRole("link", { name: /^Account/ }),
  ).toBeVisible();

  // Ontology opens on its Explorer, listed above Object types; nested routes
  // keep their section active.
  await nav.getByRole("link", { name: "Ontology", exact: true }).click();
  await expect(page).toHaveURL(/\/ontology\/explore$/);
  await expect(nav.locator(".hf-subnav a")).toHaveText([
    "Explorer",
    "Object types",
  ]);
  await expect(
    nav.getByRole("link", { name: "Ontology", exact: true }),
  ).toHaveClass(/is-active/);
  await expect(
    nav.getByRole("link", { name: "Explorer", exact: true }),
  ).toHaveAttribute("aria-current", "page");
  // Data is one page of connections and their tables; the old URL lands there.
  await page.goto("/data/connections");
  await expect(page).toHaveURL(/\/data$/);
  await expect(
    page.getByRole("heading", { name: "Data", level: 1 }),
  ).toBeVisible();
  await expect(nav.getByRole("link", { name: "Connections" })).toHaveCount(0);

  // Command palette: search resources, then keyboard navigation.
  await page.keyboard.press("ControlOrMeta+k");
  const palette = page.getByRole("dialog", { name: "Search your workspace" });
  await expect(palette).toBeVisible();
  await palette.getByRole("combobox").fill("account");
  await palette
    .getByRole("group", { name: "Object types" })
    .getByRole("option", { name: /^Account/ })
    .click();
  await expect(page).toHaveURL(/\/ontology\/types\//);
  await expect(
    page.getByRole("heading", { name: "Account", exact: true }),
  ).toBeVisible();
  await expect(
    nav.getByRole("link", { name: "Ontology", exact: true }),
  ).toHaveClass(/is-active/);
  await page.keyboard.press("ControlOrMeta+k");
  await palette.getByRole("combobox").fill("analyst");
  await expect(palette.getByRole("option").first()).toHaveAttribute(
    "aria-selected",
    "true",
  );
  await page.keyboard.press("Enter");
  // Analyst has no landing page: with no chats yet it opens Home, where
  // chats start, and the history under Analyst says so.
  await expect(page).toHaveURL(/\/$/);
  await expect(palette).toHaveCount(0);
  await expect(nav.getByText("Ask on Home to start a chat")).toBeVisible();
  // Asking from search starts a chat as well: the chat opens and heads the
  // history, marked as the current page. Chats are not section links.
  const question = "Which accounts have the most events?";
  await page.keyboard.press("ControlOrMeta+k");
  await palette.getByRole("combobox").fill(question);
  await palette.getByRole("option", { name: /^Ask Analyst:/ }).click();
  await expect(page).toHaveURL(/\/analyst\/[^/]+$/);
  await expect(palette).toHaveCount(0);
  const chats = nav.getByRole("list", { name: "Chats" });
  await expect(chats.getByRole("link", { name: question })).toHaveAttribute(
    "aria-current",
    "page",
  );
  expect(
    (await nav.locator(".hf-nav-link").allInnerTexts()).map((t) => t.trim()),
  ).toEqual(sections);
  // Search finds the chat by its question.
  await page.keyboard.press("ControlOrMeta+k");
  await palette.getByRole("combobox").fill("accounts have the most");
  await expect(
    palette
      .getByRole("group", { name: "Chats" })
      .getByRole("option", { name: new RegExp("^" + question.slice(0, -1)) }),
  ).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(palette).toHaveCount(0);
  // New chat returns to Home's ask box, ready to type.
  await nav.getByRole("link", { name: "New chat", exact: true }).click();
  await expect(page).toHaveURL(/\/$/);
  await expect(
    page.getByRole("textbox", { name: "Ask anything about your data" }),
  ).toBeFocused();
  // Dashboards are gone from search; old dashboard links open Home.
  await page.keyboard.press("ControlOrMeta+k");
  await palette.getByRole("combobox").fill("dashboards");
  await expect(
    palette.getByRole("option", { name: /^Dashboards/ }),
  ).toHaveCount(0);
  await page.keyboard.press("Escape");
  await expect(palette).toHaveCount(0);

  // Unknown routes and old paths.
  await page.goto("/nowhere");
  await expect(page.getByText("We couldn’t find that page")).toBeVisible();
  for (const old of ["/advanced", "/pipelines", "/explore"]) {
    await page.goto(old);
    await expect(page).toHaveURL(/\/data$/);
  }
  for (const old of ["/activity", "/dashboards", "/dashboards/Overview"]) {
    await page.goto(old);
    await expect(page).toHaveURL(/\/$/);
  }
  await page.goto("/records?type=Account");
  await expect(page).toHaveURL(/\/ontology\/explore\?type=Account$/);

  // The collapsed sidebar keeps accessible names and survives a reload.
  await page.getByRole("button", { name: "Collapse sidebar" }).click();
  await expect(
    nav.getByRole("link", { name: "Data", exact: true }),
  ).toBeVisible();
  await page.reload();
  // Menus open beside the 60px rail, fully visible rather than clipped.
  await page.getByRole("button", { name: /^Workspace:/ }).click();
  const switcher = page.getByRole("menu", { name: /^Workspace:/ });
  await expect(switcher).toBeVisible();
  expect(
    await switcher.evaluate((el) => {
      const r = el.getBoundingClientRect();
      const inside = (x: number, y: number) =>
        el.contains(document.elementFromPoint(x, y));
      return (
        r.width >= 220 &&
        r.left >= 0 &&
        r.right <= window.innerWidth &&
        inside(r.left + 4, r.top + 4) &&
        inside(r.right - 4, r.top + 4) &&
        inside(r.right - 4, r.bottom - 4)
      );
    }),
  ).toBe(true);
  await page.keyboard.press("Escape");
  await expect(switcher).toHaveCount(0);
  await page.getByRole("button", { name: "Expand sidebar" }).click();

  // The workspace switcher lists workspaces and creates new ones.
  await page.getByRole("button", { name: /^Workspace:/ }).click();
  const menu = page.getByRole("menu", { name: /^Workspace:/ });
  await expect(
    menu.getByRole("menuitemradio", { name: new RegExp(ws.name) }),
  ).toHaveAttribute("aria-checked", "true");
  await menu.getByRole("menuitem", { name: "Create workspace" }).click();
  const create = page.getByRole("dialog", { name: "Create a workspace" });
  await create.getByLabel("Workspace name").fill("Shell created");
  await create.getByRole("button", { name: "Create workspace" }).click();
  await expect(page).toHaveURL(/\/onboarding$/);
  await page.evaluate(
    (id) => localStorage.setItem("foundry.workspace", id),
    ws.id,
  );

  // Phone layout: drawer navigation, no sideways scrolling.
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/");
  await expect(
    page.getByRole("textbox", { name: "Ask anything about your data" }),
  ).toBeVisible();
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= window.innerWidth,
    ),
  ).toBe(true);
  await page.getByRole("button", { name: "Open navigation" }).click();
  const drawer = page.getByRole("dialog", { name: "Navigation" });
  // A visible close control takes focus; the drawer spans the full height.
  const close = drawer.getByRole("button", { name: "Close navigation" });
  await expect(close).toBeFocused();
  expect(
    await drawer.evaluate(
      (el) => el.getBoundingClientRect().bottom >= window.innerHeight - 1,
    ),
  ).toBe(true);
  await close.click();
  await expect(drawer).toHaveCount(0);
  await page.getByRole("button", { name: "Open navigation" }).click();
  await drawer.getByRole("link", { name: "Ontology", exact: true }).click();
  await expect(page).toHaveURL(/\/ontology\/explore$/);
  await expect(drawer).toHaveCount(0);
});

import { test, expect, type Page } from "@playwright/test";
import { api, openApp } from "./support/workspace";

// A dataset of 160 rows, open on its first page of 50.
async function fixture(page: Page, label: string) {
  await openApp(page);
  const ws = await api(page, "/workspaces", { name: label + " " + Date.now() });
  const base = `/workspaces/${ws.id}`;
  const ds = await api(page, base + "/ingest", {
    name: label,
    rows: Array.from({ length: 160 }, (_, i) => ({
      id: i,
      category: "Original " + i,
    })),
  });
  await page.evaluate(
    (id: string) => localStorage.setItem("foundry.workspace", id),
    ws.id,
  );
  await page.goto(`/data/datasets/${ds.id}`);
  await expect(page.getByText("Sample · 1–50", { exact: true })).toBeVisible();
  return { base, ds };
}

// The page refetches the dataset when the browser comes back online, once
// the query is older than its 5-second staleTime.
async function reconnect(page: Page, base: string, dsId: string) {
  const response = page.waitForResponse(
    (r) =>
      r.request().method() === "GET" &&
      new URL(r.url()).pathname ===
        `/api/v1${base}/resources/dataset/${dsId}` &&
      r.status() === 200,
  );
  await page.waitForTimeout(5100);
  await page.context().setOffline(true);
  await expect.poll(() => page.evaluate(() => navigator.onLine)).toBe(false);
  await page.context().setOffline(false);
  await expect.poll(() => page.evaluate(() => navigator.onLine)).toBe(true);
  return (await (await response).json()).data.activeVersion;
}

const previewOf = (base: string, dsId: string, version: string) =>
  `/api/v1${base}/datasets/${dsId}/versions/${version}/preview`;

test("a new current snapshot starts on its first page", async ({ page }) => {
  const { base, ds } = await fixture(page, "Current page refresh");
  await page.getByRole("button", { name: "Next", exact: true }).click();
  await expect(
    page.getByText("Sample · 51–100", { exact: true }),
  ).toBeVisible();
  const changed = await api(page, base + "/ingest", {
    name: ds.name,
    datasetId: ds.id,
    rows: [{ id: 777, category: "Current only row" }],
  });
  expect(changed.data.activeVersion).not.toBe(ds.data.activeVersion);
  const preview = page.waitForResponse(
    (r) =>
      r.request().method() === "POST" &&
      new URL(r.url()).pathname ===
        previewOf(base, ds.id, changed.data.activeVersion),
  );
  expect(await reconnect(page, base, ds.id)).toBe(changed.data.activeVersion);
  expect((await preview).request().postDataJSON()).toEqual({
    offset: 0,
    limit: 50,
  });
  await expect(
    page.getByRole("cell", { name: "Current only row", exact: true }),
  ).toBeVisible();
  await expect(page.getByText("Sample · 1–1", { exact: true })).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Previous", exact: true }),
  ).toBeDisabled();
});

test("a refetch of the same snapshot keeps the page", async ({ page }) => {
  const { base, ds } = await fixture(page, "Same version metadata");
  await page.getByRole("button", { name: "Next", exact: true }).click();
  await expect(
    page.getByText("Sample · 51–100", { exact: true }),
  ).toBeVisible();
  await page.getByText("Details", { exact: true }).click();
  await page
    .getByRole("textbox", { name: "Dataset description", exact: true })
    .fill("Edited metadata");
  const metadata = page.waitForResponse(
    (r) =>
      r.request().method() === "GET" &&
      new URL(r.url()).pathname ===
        `/api/v1${base}/resources/dataset/${ds.id}` &&
      r.status() === 200,
  );
  const preview = page.waitForResponse(
    (r) =>
      r.request().method() === "POST" &&
      new URL(r.url()).pathname ===
        previewOf(base, ds.id, ds.data.activeVersion) &&
      r.request().postDataJSON()?.offset === 50 &&
      r.status() === 200,
  );
  await page
    .getByRole("button", { name: "Save description", exact: true })
    .click();
  expect((await (await metadata).json()).data.activeVersion).toBe(
    ds.data.activeVersion,
  );
  expect((await (await preview).json()).rows).toHaveLength(50);
  await expect(
    page.getByText("Sample · 51–100", { exact: true }),
  ).toBeVisible();
  await expect(
    page.getByRole("cell", { name: "Original 50", exact: true }),
  ).toBeVisible();
});

test("a chosen historical snapshot keeps its page; choosing resets it", async ({
  page,
}) => {
  const { base, ds } = await fixture(page, "Historical page retention");
  const second = await api(page, base + "/ingest", {
    name: ds.name,
    datasetId: ds.id,
    rows: Array.from({ length: 160 }, (_, i) => ({
      id: i,
      category: "Second " + i,
    })),
  });
  expect(await reconnect(page, base, ds.id)).toBe(second.data.activeVersion);
  const selector = page.getByRole("combobox", {
    name: "Snapshot",
    exact: true,
  });
  await selector.selectOption(ds.data.activeVersion);
  await expect(
    page.getByRole("cell", { name: "Original 0", exact: true }),
  ).toBeVisible();
  await page.getByRole("button", { name: "Next", exact: true }).click();
  await expect(
    page.getByText("Sample · 51–100", { exact: true }),
  ).toBeVisible();
  const third = await api(page, base + "/ingest", {
    name: ds.name,
    datasetId: ds.id,
    rows: [{ id: 888, category: "Newest current row" }],
  });
  expect(await reconnect(page, base, ds.id)).toBe(third.data.activeVersion);
  await expect(selector).toHaveValue(ds.data.activeVersion);
  await expect(
    page.getByText("Sample · 51–100", { exact: true }),
  ).toBeVisible();
  await expect(
    page.getByRole("cell", { name: "Original 50", exact: true }),
  ).toBeVisible();
  await selector.selectOption(third.data.activeVersion);
  await expect(
    page.getByRole("cell", { name: "Newest current row", exact: true }),
  ).toBeVisible();
  await expect(page.getByText("Sample · 1–1", { exact: true })).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Previous", exact: true }),
  ).toBeDisabled();
});
